.poster {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  height: 220px;
  margin: 16px;
  padding: 20px;
  border-radius: 12px;
  font-family: system-ui, sans-serif;
  background-image: repeating-linear-gradient(45deg, #fdba74 0 14px, #fef3c7 14px 28px);
