/* ---- Solution ---- */
.poster {
  background-image:
    linear-gradient(transparent 30%, rgb(0 0 0 / 0.75)),
    repeating-linear-gradient(45deg, #fdba74 0 14px, #fef3c7 14px 28px);
  color: #ffffff;
}
